def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        base = 18.0 if hp > 3 else 45.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    aggressive_count = 0
    desperate_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            try:
                b = float(bid)
                prev_bids.append(b)
                if b >= 85.0:
                    aggressive_count += 1
                if b >= 110.0:
                    desperate_count += 1
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0

    competitors = 1 + len(alive_opponents)
    expected_units = supply / float(WATER_REQ)
    tight_supply = expected_units < competitors * 0.55
    medium_supply = expected_units < competitors * 0.8

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if tight_supply:
        danger += 2
    elif medium_supply:
        danger += 1

    if day >= 8:
        danger += 1

    if danger >= 6:
        bid = max(95.0, highest_prev + 2.0)
    elif danger >= 4:
        bid = max(72.0, min(96.0, highest_prev * 0.92 + 3.0))
    elif danger >= 2:
        if aggressive_count >= 2:
            bid = 26.0 if hp > 4 else 68.0
        else:
            bid = max(38.0, lowest_prev + 2.0 if prev_bids else 42.0)
    else:
        if aggressive_count >= 2:
            bid = 12.0
        elif highest_prev <= 40.0 and prev_bids:
            bid = highest_prev + 2.0
        else:
            bid = 20.0

    reserve_days = 3 if day <= 7 else 1
    reserve_budget = reserve_days * DAILY_SALARY
    max_affordable = budget
    if budget > reserve_budget:
        max_affordable = budget - reserve_budget + DAILY_SALARY * 0.35

    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    # If no opponents alive, bid conservatively.
    if not alive_opps:
        bid = DAILY_SALARY * 0.4
        return float(min(my_budget, bid))

    # Read yesterday bids of alive opponents.
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace') or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent pressure from yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Base target: mid-high to beat likely aggressive bidders, but not as high as their max.
    # Use our urgency to scale.
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 4:
        urgency = 0.7
    elif my_no_water_days >= 2:
        urgency = 0.6
    else:
        urgency = 0.4

    # Supply affects how many bidders might be satisfied; lower supply -> higher chance of competition.
    supply_factor = 0.55
    if supply <= float(MIN_SUPPLY):
        supply_factor = 0.8
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.6

    # If yesterday highest bid was very high, reduce slightly to avoid overpaying into a war.
    # Otherwise, increase to secure water.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        war_mode = True
    else:
        war_mode = False

    # Candidate bid anchored around a fraction of DAILY_SALARY.
    if war_mode:
        base = DAILY_SALARY * (0.62 + 0.18 * urgency)
        # Nudge upward if we are in immediate danger.
        if my_hp <= 2 or my_no_water_days >= 3:
            base = DAILY_SALARY * (0.72 + 0.18 * urgency)
        # Also consider second-highest: try to be above it when budgets allow.
        if second_prev_bid > 0:
            base = max(base, second_prev_bid + 1.5)
    else:
        base = DAILY_SALARY * (0.55 + 0.25 * urgency)
        if highest_prev_bid > 0:
            base = max(base, min(DAILY_SALARY * 0.8, highest_prev_bid * 0.85 + 2.0))

    # Apply supply factor.
    bid = base * supply_factor

    # Safety caps: never bid more than we can afford; also avoid bidding above a reasonable ceiling.
    ceiling = DAILY_SALARY * 0.95
    bid = min(bid, ceiling)

    # If our budget is low, bid just enough to stay competitive.
    if my_budget < DAILY_SALARY * 0.3:
        bid = min(my_budget, DAILY_SALARY * 0.55)

    # Final clamp.
    bid = max(0.0, min(my_budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev = max(yesterday_bids) if yesterday_bids else 0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(max_prev + 5.0, DAILY_SALARY * 0.9))

    if supply < 18:
        return min(my_status['budget'], max(max_prev + 2.0, DAILY_SALARY * 0.7))

    return min(my_status['budget'], max(max_prev * 0.9, DAILY_SALARY * 0.4))
